39	function compileFormSchema(node) {
40	  if (!Object.hasOwn(node, 'schema') || node.schema === undefined) return null;
41	  if (!isUsableObject(node.schema)) {
42	    throw new Error(`form node ${node.id}: schema must be an object`);
43	  }
44	  if (!Array.isArray(node.schema.fields)) {
45	    throw new Error(`form node ${node.id}: schema.fields must be an array`);
46	  }
47	
48	  const seenSegments = [];
49	  const compiled = [];
50	  node.schema.fields.forEach((field, index) => {
51	    const label = `form node ${node.id} field ${field && isUsableObject(field) && typeof field.path === 'string' && field.path ? field.path : `#${index}`}`;
52	    if (!isUsableObject(field)) {
53	      throw new Error(`${label}: field must be an object`);
54	    }
55	    if (typeof field.path !== 'string' || field.path.length === 0) {
56	      throw new Error(`form node ${node.id} field #${index}: path must be a non-empty string`);
57	    }
58	    const segments = field.path.split('.');
59	    if (segments.some(part => part.length === 0)) {
60	      throw new Error(`${label}: path must not contain empty segments`);
61	    }
62	    if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
63	      throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
64	    }
65	    for (const previous of seenSegments) {
66	      const shared = Math.min(previous.length, segments.length);
67	      let prefix = true;
68	      for (let i = 0; i < shared; i += 1) {
69	        if (previous[i] !== segments[i]) { prefix = false; break; }
70	      }
71	      if (prefix && previous.length === segments.length) {
72	        throw new Error(`${label}: duplicate field path`);
73	      }
74	      if (prefix) {
75	        throw new Error(`${label}: field paths must not be parent and child of each other`);
76	      }
77	    }
78	    seenSegments.push(segments);
79	
80	    if (!FIELD_TYPES.has(field.type)) {
81	      throw new Error(`${label}: unknown field type ${field.type}`);
82	    }
83	    const spec = { path: field.path, segments, type: field.type, required: false, hasDefault: false };
84	
85	    if (Object.hasOwn(field, 'required')) {
86	      if (typeof field.required !== 'boolean') {
87	        throw new Error(`${label}: required must be a boolean`);
88	      }
89	      spec.required = field.required;
90	    }
91	
92	    const applicableBounds = field.type === 'string' ? STRING_BOUNDS
93	      : (field.type === 'number' || field.type === 'integer') ? NUMBER_BOUNDS
94	      : new Set();
95	    for (const bound of ['minLength', 'maxLength', 'min', 'max']) {
96	      if (!Object.hasOwn(field, bound) || field[bound] === undefined) continue;
97	      if (!applicableBounds.has(bound)) {
98	        throw new Error(`${label}: ${bound} does not apply to ${field.type} fields`);
99	      }
100	      const value = field[bound];
101	      if (field.type === 'string') {
102	        if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
103	          throw new Error(`${label}: ${bound} must be a non-negative integer`);
104	        }
105	      } else if (typeof value !== 'number' || !Number.isFinite(value)) {
106	        throw new Error(`${label}: ${bound} must be a finite number`);
107	      }
108	      spec[bound] = value;
109	    }
110	    if (spec.minLength !== undefined && spec.maxLength !== undefined && spec.minLength > spec.maxLength) {
111	      throw new Error(`${label}: minLength must not be greater than maxLength`);
112	    }
113	    if (spec.min !== undefined && spec.max !== undefined && spec.min > spec.max) {
114	      throw new Error(`${label}: min must not be greater than max`);
115	    }
116	
117	    if (Object.hasOwn(field, 'default') && field.default !== undefined) {
118	      const fallback = field.default;
119	      if (!valueMatchesType(fallback, spec.type)) {
120	        throw new Error(`${label}: default value does not match field type ${spec.type}`);
121	      }
122	      if (!valueSatisfiesBounds(fallback, spec)) {
123	        throw new Error(`${label}: default value violates field constraints`);
124	      }
125	      spec.hasDefault = true;
126	      spec.default = fallback;
127	    }
128	
129	    compiled.push(spec);
130	  });
131	
132	  return compiled;
133	}
134	
135	const MAX_CONDITION_DEPTH = 32;
136	
137	function parsePathSegments(path, label) {
138	  if (typeof path !== 'string' || path.length === 0) {
139	    throw new Error(`${label}: path must be a non-empty string`);
140	  }
141	  const segments = path.split('.');
142	  if (segments.some(part => part.length === 0)) {
143	    throw new Error(`${label}: path must not contain empty segments`);
144	  }
145	  if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
146	    throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
147	  }
148	  return segments;
149	}
150	
151	function isComparableConstant(value) {
152	  return value === null || typeof value === 'string' || typeof value === 'boolean'
153	    || (typeof value === 'number' && Number.isFinite(value));
154	}
155	
156	function toComparableNumber(value) {
157	  // Objects and arrays never participate in numeric comparison, even though
158	  // Number([]) === 0; everything else uses JS numeric conversion.
159	  if (value !== null && typeof value === 'object') return null;
160	  const converted = Number(value);
161	  return Number.isFinite(converted) ? converted : null;
162	}
163	
164	// Validates an output reference of the shape
165	// `{ "nodeId": "risk-check", "path": "risk.score" }` (path optional). The
166	// reference itself must be a non-array object, nodeId must name an action
167	// node in this definition (matched as a whole string — dots are literal),
168	// and path, when present, follows the same segment rules as input paths.
169	function compileOutputReference(ref, nodes, label) {
170	  if (!isUsableObject(ref)) {
171	    throw new Error(`${label}: output reference must be a non-array object`);
172	  }
173	  if (typeof ref.nodeId !== 'string' || ref.nodeId.length === 0) {
174	    throw new Error(`${label}: nodeId must be a non-empty string naming an action node`);
175	  }
176	  const target = nodes.get(ref.nodeId);
177	  if (!target) {
178	    throw new Error(`${label}: nodeId "${ref.nodeId}" does not name a node in this workflow`);
179	  }
180	  if (target.type !== 'action') {
181	    throw new Error(`${label}: nodeId "${ref.nodeId}" must name an action node`);
182	  }
183	  let segments = [];
184	  if (Object.hasOwn(ref, 'path')) {
185	    segments = parsePathSegments(ref.path, `${label} path`);
186	  }
187	  return { nodeId: ref.nodeId, segments };
188	}
189	
190	// Walks every condition node (including untaken branches) and turns it into a
191	// pre-validated, pre-resolved structure. Any malformed condition throws with a
192	// node id and a `$`-style child position, before the workflow can execute.
193	function compileCondition(condition, nodes, nodeId, position = '$', depth = 1) {
194	  if (depth > MAX_CONDITION_DEPTH) {
195	    throw new Error(`condition node ${nodeId} at ${position}: conditions must not be nested deeper than ${MAX_CONDITION_DEPTH} levels`);
196	  }
197	  if (!isUsableObject(condition)) {
198	    throw new Error(`condition node ${nodeId} at ${position}: condition must be an object`);
199	  }
200	
201	  const comboKeys = [];
202	  if (Object.hasOwn(condition, 'all')) comboKeys.push('all');
203	  if (Object.hasOwn(condition, 'any')) comboKeys.push('any');
204	  if (Object.hasOwn(condition, 'not')) comboKeys.push('not');
205	  if (comboKeys.length > 1) {
206	    throw new Error(`condition node ${nodeId} at ${position}: condition must use only one of all, any or not`);
207	  }
208	
209	  const comparisonKeys = ['field', 'outputField', 'operator', 'value', 'valueField', 'valueOutputField'];
210	  const presentComparisonKeys = comparisonKeys.filter(key => Object.hasOwn(condition, key));
211	
212	  if (comboKeys.length === 1) {
213	    if (presentComparisonKeys.length > 0) {
214	      throw new Error(`condition node ${nodeId} at ${position}: ${comboKeys[0]} condition must not mix in field, outputField, operator, value, valueField or valueOutputField`);
215	    }
216	    const key = comboKeys[0];
217	    if (key === 'not') {
218	      return { kind: 'not', child: compileCondition(condition.not, nodes, nodeId, `${position}.not`, depth + 1) };
219	    }
220	    const childList = condition[key];
221	    if (!Array.isArray(childList)) {
222	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must be an array of conditions`);
223	    }
224	    if (childList.length === 0) {
225	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must not be empty`);
226	    }
227	    // A non-empty array may still carry length without a condition at every
228	    // slot: a child deleted through the JavaScript API can leave a hole, or
229	    // the array may have been allocated with gaps only. A missing slot is a
230	    // definition error at its own original index — it is never treated as
231	    // false, skipped over or filled in — so it is reported even when an
232	    // earlier sibling would already short-circuit the compound. Explicit
233	    // undefined/null entries are not holes: they remain present and fall
234	    // through to the ordinary "condition must be an object" rejection.
235	    const children = [];
236	    for (let index = 0; index < childList.length; index += 1) {
237	      if (!Object.hasOwn(childList, index)) {
238	        throw new Error(`condition node ${nodeId} at ${position}.${key}[${index}]: ${key}[${index}] is a missing child condition`);
239	      }
240	      children.push(
241	        compileCondition(childList[index], nodes, nodeId, `${position}.${key}[${index}]`, depth + 1));
242	    }
243	    return { kind: key, children };
244	  }
245	
246	  const where = `condition node ${nodeId} at ${position}`;
247	  const hasField = Object.hasOwn(condition, 'field');
248	  const hasOutputField = Object.hasOwn(condition, 'outputField');
249	  if ((!hasField && !hasOutputField) || !Object.hasOwn(condition, 'operator')) {
250	    throw new Error(`${where}: condition must be a comparison (field and operator) or a compound (all, any or not)`);
251	  }
252	  if (hasField && hasOutputField) {
253	    throw new Error(`${where}: condition must specify exactly one of field or outputField`);
254	  }
255	
256	  if (!['eq', 'gte', 'lte', 'exists'].includes(condition.operator)) {
257	    throw new Error(`${where}: unknown condition operator: ${condition.operator}`);
258	  }
259	
260	  let left;
261	  if (hasField) {
262	    left = { kind: 'input', label: 'field', segments: parsePathSegments(condition.field, `${where} field`) };
263	  } else {
264	    left = {
265	      kind: 'output', label: 'outputField',
266	      ref: compileOutputReference(condition.outputField, nodes, `${where} outputField`),
267	    };
268	  }
269	
270	  if (condition.operator === 'exists') {
271	    const unexpected = presentComparisonKeys.filter(key =>
272	      key === 'value' || key === 'valueField' || key === 'valueOutputField');
273	    if (unexpected.length > 0) {
274	      throw new Error(`${where}: exists only takes field and operator (outputField may name the left side)`);
275	    }
276	    return { kind: 'comparison', operator: 'exists', left };
277	  }
278	
279	  const hasValue = Object.hasOwn(condition, 'value');
280	  const hasValueField = Object.hasOwn(condition, 'valueField');
281	  const hasValueOutput = Object.hasOwn(condition, 'valueOutputField');
282	  const rightCount = [hasValue, hasValueField, hasValueOutput].filter(Boolean).length;
283	  if (rightCount !== 1) {
284	    throw new Error(`${where}: condition must specify exactly one of value or valueField (or valueOutputField)`);
285	  }
286	
287	  let right;
288	  if (hasValue) {
289	    if (!isComparableConstant(condition.value)) {
290	      throw new Error(`${where}: value must be a string, finite number, boolean or null`);
291	    }
292	    right = { kind: 'constant', label: 'value', value: condition.value };
293	    if (condition.operator !== 'eq') {
294	      const numericValue = toComparableNumber(condition.value);
295	      if (numericValue === null) {
296	        throw new Error(`${where}: value for ${condition.operator} must convert to a finite number`);
297	      }
298	      right.numericValue = numericValue;
299	    }
300	  } else if (hasValueField) {
301	    if (typeof condition.valueField !== 'string') {
302	      throw new Error(`${where} valueField: path must be a non-empty string`);
303	    }
304	    right = {
305	      kind: 'input', label: 'valueField',
306	      segments: parsePathSegments(condition.valueField, `${where} valueField`),
307	    };
308	  } else {
309	    right = {
310	      kind: 'output', label: 'valueOutputField',
311	      ref: compileOutputReference(condition.valueOutputField, nodes, `${where} valueOutputField`),
312	    };
313	  }
314	
315	  return { kind: 'comparison', operator: condition.operator, left, right };
316	}
317	
318	const successorTargets = new WeakMap();
319	
320	const RETRY_FIELDS = ['attempts', 'initialDelayMs', 'backoffFactor', 'maxDelayMs'];
321	const DEFAULT_RETRY = { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
322	
323	function isIntegerIn(value, min, max) {
324	  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
325	}
326	
327	// A retry block is either absent (one attempt, no waiting) or present with all
328	// four parameters together, each within the same ranges the engine enforces
329	// for business action retries and compensation retries alike.
330	function compileRetry(config, label) {
331	  if (!isUsableObject(config)) {
332	    throw new Error(`${label}: retry must be an object`);
333	  }
334	  const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
335	  if (missing.length > 0) {
336	    throw new Error(`${label}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
337	  }
338	  if (!isIntegerIn(config.attempts, 1, 10)) {
339	    throw new Error(`${label}: retry.attempts must be an integer between 1 and 10`);
340	  }
341	  if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
342	    throw new Error(`${label}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
343	  }
344	  if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
345	    throw new Error(`${label}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
346	  }
347	  if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
348	    || config.backoffFactor < 1 || config.backoffFactor > 4) {
349	    throw new Error(`${label}: retry.backoffFactor must be a finite number between 1 and 4`);
350	  }
351	  if (config.maxDelayMs < config.initialDelayMs) {
352	    throw new Error(`${label}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
353	  }
354	  return {
355	    attempts: config.attempts,
356	    initialDelayMs: config.initialDelayMs,
357	    backoffFactor: config.backoffFactor,
358	    maxDelayMs: config.maxDelayMs,
359	  };
360	}
361	
362	// An action node either keeps the legacy `message` behavior, names a business
363	// operation the caller supplies at run time, and/or declares a compensation
364	// operation that undoes its business effect. Both retry blocks are optional
365	// and, absent, mean exactly one attempt with no waiting.
366	function compileAction(node) {
367	  let name = null;
368	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
369	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
370	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
371	    }
372	    name = node.operation;
373	  }
374	
375	  let retry = { ...DEFAULT_RETRY };
376	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
377	    if (!name) {
378	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
379	    }
380	    retry = compileRetry(node.retry, `action node ${node.id}`);
381	  }
382	
383	  let compensation = null;
384	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
385	    if (!isUsableObject(node.compensation)) {
386	      throw new Error(`action node ${node.id}: compensation must be an object`);
387	    }
388	    if (!name) {
389	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
390	    }
391	    const config = node.compensation;
392	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
393	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
394	    }
395	    let compRetry = { ...DEFAULT_RETRY };
396	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
397	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
398	    }
399	    compensation = { name: config.operation, retry: compRetry };
400	  }
401	
402	  // A legacy message action (no operation) is validated through the single
403	  // configured-value gate (assertConfiguredCopy below) — the same rule, with
404	  // action-specific wording, that end-node results use — covering every
405	  // message action including ones on untaken branches and entry-unreachable
406	  // ones. An action that names an operation ignores its message entirely, so
407	  // an unused uncloneable or shared-memory message is never rejected for it.
408	  // The gate only proves the message was safe as it was then; the same rule
409	  // is re-enforced at the action's own execution moment by readConfiguredCopy.
410	  if (name === null) {
411	    assertConfiguredCopy(node, 'message', ACTION_MESSAGE_COPY_ERRORS);
412	  }
413	
414	  return { name, retry, compensation };
415	}
416	
417	// The two failure kinds a node-configured value can produce, shared by
418	// definition validation (assertConfiguredCopy below) and the execution-time
419	// capture (readConfiguredCopy below): the value cannot be structured-cloned at
420	// all, or it clones but the clone retains shared memory. Uncloneability takes
421	// precedence when a value carries both, at both moments. Each node kind keeps
422	// its own wording — an action's message and an end node's result fail with the
423	// node-specific text the entries already exposed — and its own default for a
424	// value that is absent, undefined or null (action:<node id> for a legacy
425	// message; null for an end result), while "", 0 and false pass through
426	// untouched for both.
427	const ACTION_MESSAGE_COPY_ERRORS = {
428	  uncloneable: nodeId =>
429	    `action node ${nodeId}: message must be a structured-cloneable value (objects and arrays must not contain functions)`,
430	  sharedMemory: nodeId =>
431	    `action node ${nodeId}: message contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so shared bytes must not enter the action output`,
432	};
433	const END_RESULT_COPY_ERRORS = {
434	  uncloneable: nodeId =>
435	    `end node ${nodeId}: result must be a structured-cloneable value (objects and arrays must not contain functions)`,
436	  sharedMemory: nodeId =>
437	    `end node ${nodeId}: result contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this end result is not supported`,
438	};
439	
440	// The single independent-copy rule for a value a node configures — a legacy
441	// action's `message` and an end node's `result` both go through here, so the
442	// cloneability and retained-shared-memory rules are maintained in exactly one
443	// place and the two node kinds can never drift apart. It is invoked at two
444	// moments, and each moment keeps its original root-read protocol:
445	//
446	//  1. At validation time (assertConfiguredCopy), for every such node in the
447	//     definition — including nodes on untaken branches and nodes the entry
448	//     cannot reach — so a statically invalid value is rejected before any
449	//     node, business operation or compensation can run. An absent own
450	//     property is not read at all; the gate performs the first root read and
451	//     only an own, defined value reaches the clone, which performs the root's
452	//     second read itself (a throwing root accessor propagates from the gate
453	//     exactly as before).
454	//  2. At the node's own execution moment (readConfiguredCopy), against the
455	//     value actually about to be saved: the root is read exactly once and the
456	//     value that read produced is cloned, so validation cannot pin the result
457	//     — an enumerable getter's later answer and a preceding business
458	//     operation's or another activated branch's mutation are both captured.
459	//
460	// At either moment every nested enumerable accessor is read only by
461	// structuredClone's own read — there is no separate inspection pass over the
462	// original, so a getter's return order is never disturbed and the value the
463	// clone's read produced is both what is judged and what is saved (a legal
464	// value whose getter answers with a different ordinary value at execution
465	// time records that fresh value rather than the stale validation-time one). A
466	// root getter that throws on execution's single read, a nested getter that
467	// throws while the clone reads it, and a value that cannot be cloned at all
468	// (a bare function) all surface as the same uncloneable error.
469	//
470	// The copy itself is produced by independentCopy — the one clone-then-judge
471	// rule every saved value in this engine goes through (see its comment for why
472	// cloning must precede the shared-memory traversal and why uncloneability
473	// takes precedence). Only the wording of the failure is node-specific here.
474	//
475	// Any failure is thrown as an ordinary Error naming the node (errors[kind])
476	// rather than recorded as a run status: the synchronous entry propagates it
477	// and the asynchronous entry's rejected Promise carries it. It is never an
478	// action_failed — neither node kind has a retry budget — it neither consumes
479	// business-action retries nor triggers compensation, and no output/result is
480	// recorded for the node. At execution, an absent, undefined or null value
481	// becomes `absentValue` (action:<node id> for messages, null for results),
482	// while "", 0 and false pass through untouched.
483	function configuredCopy(node, property, errors, options) {
484	  const validation = options !== undefined && options.validation === true;
485	
486	  if (validation) {
487	    // Preserve the validation gate exactly: no read at all for a missing own
488	    // property, one unguarded gate read (a throwing root accessor propagates
489	    // raw, as the former per-node gates did), and an undefined value is left
490	    // to execution. The structuredClone argument evaluation is the root's
491	    // second — and final — read this moment; the clone itself traverses that
492	    // captured value (firing nested getters once), so no read the original
493	    // gate made is added or removed.
494	    if (!Object.hasOwn(node, property)) return;
495	    const gated = node[property];
496	    if (gated === undefined) return;
497	    const copy = independentCopy(node[property]);
498	    if (!copy.ok) throw new Error(errors[copy.reason](node.id));
499	    return;
500	  }
501	
502	  // Execution: the root value's single read. An absent, undefined or null
503	  // value takes the node kind's default (action:<node id> for messages, null
504	  // for results) without reaching structuredClone; a root getter that throws
505	  // on this read is the uncloneable error.
506	  const { absentValue } = options;
507	  let value;
