import { executeWorkflowAsync } from "./src/engine.js";

const workflow = {
  id: "repro", entry: "start",
  nodes: [
    { id: "start", type: "trigger", next: "form-one" },
    { id: "form-one", type: "form", next: "act", schema: { fields: [
      { path: "failure.message.label", type: "string", default: "web" },
      { path: "failure.message.meta.source", type: "string", default: "form" },
    ] } },
    { id: "act", type: "action", operation: "op", compensation: { operation: "undo" }, next: "done" },
    { id: "done", type: "end", result: "ok" },
  ],
};

const failure = new Error();
const caller = { failure, other: "kept" };
const seen = [];
const result = await executeWorkflowAsync(workflow, caller, {
  op: (input) => {
    seen.push({
      isError: input.failure instanceof Error,
      messageType: typeof input.failure.message,
      label: input.failure.message.label,
      meta: input.failure.message.meta,
      other: input.other,
    });
    // mutate this copy
    input.failure.message.label = "hacked";
    input.failure.message.newParent = { deep: true };
    return "A";
  },
  undo: (input) => {
    seen.push({ undoMessage: input.failure.message, isError: input.failure instanceof Error });
    return "undone";
  },
});
console.log("status:", result.status);
console.log("live:", JSON.stringify(result.context.input.failure.message));
console.log("action/comp saw:", JSON.stringify(seen, null, 2));
console.log("caller own message:", Object.hasOwn(caller.failure, "message"));
'

