input.command:
node --input-type=module -e '
import { executeWorkflowAsync } from "./src/engine.js";
const wf = { id:"w", entry:"s", nodes:[
  {id:"s",type:"trigger",next:"f"},
  {id:"f",type:"form",next:"a",schema:{fields:[
    {path:"failure.cause.cause.message.label",type:"string",default:"deep"},
  ]}},
  {id:"a",type:"action",operation:"op",next:"d"},
  {id:"d",type:"end",result:"ok"} ]};
const failure = new Error("outer", { cause: new Error("inner", { cause: new Error() }) });
let saw;
const r = await executeWorkflowAsync(wf,{failure},{op:(i)=>{
  const m = i.failure.cause.cause.message;
  saw = { isError: i.failure.cause.cause instanceof Error, label: m && m.label, type: typeof m,
          innerMsg: i.failure.cause.message };
  return "A";
}});
console.log("status:",r.status,"saw:",JSON.stringify(saw));
' && npm run demo --silent >/dev/null 2>&1 && echo "demo OK" && git status --short
